use vstd::prelude::*;

verus! {

/// Spec-level “<=” comparison lifted pointwise to sequences.
spec fn less_equal_seq(a: Seq<i8>, b: Seq<i8>) -> Seq<bool>
    recommends
        a.len() == b.len(),
{
    Seq::new(a.len(), |i: int| a[i] <= b[i])
}

fn less_equal(a: Vec<i8>, b: Vec<i8>) -> (out: Vec<bool>)
    requires
        a@.len() == b@.len(),
    ensures
        out@ == less_equal_seq(a@, b@),
        out@.len() == a@.len(),
{
    assert_eq!(a.len(), b.len(), "Input arrays must have the same length");

    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x <= y)
        .collect()
}

} // verus!

